formula=\"2d6+10\" role=\"button\" aria-label=\"Roll 2d6+10\">2d6 +10</span>)</p></div></div> <div class=\"statblock-markdown svelte-1c3hzq4\"><p dir=\"auto\">20 DMG</p></div> </div></div><div class=\"statblock-item-container rule-container\"><div class=\"tapered-rule svelte-k72li0\"></div></div><div class=\"statblock-item-container text-container \"> <div class=\"line\"><div class=\"statblock-markdown svelte-1c3hzq4\"><p dir=\"auto\">Une simple poignée qui peut se tenir à <strong>1 ou 2 mains</strong>. Utiliser la magie permet de matérialiser une arme de la forme de son choix selon la magie de son choix. On l'appelle <strong>Excaliburne</strong>.</p></div></div></div></details></div></div></div></div> <div class=\"bar svelte-zyyfbl\"></div></div> </div></div>\n<div class=\"block-language-statblock statblock-plugin-container\" data-live-statblock=\"{&quot;path&quot;:&quot;Jeu/Sessions du Masque/Joueurs/Haelrak.md&quot;,&quot;index&quot;:2,&quot;layout&quot;:[{&quot;type&quot;:&quot;javascript&quot;,&quot;id&quot;:&quot;ac0c0de00001&quot;,&quot;code&quot;:&quot;const app = property?.app ?? window.app;\\nconst num = (v) =&gt; (String(v ?? \\&quot;\\&quot;).match(/[+-]?\\\\s*\\\\d+(\\\\.\\\\d+)?/g) ?? []).reduce((s, x) =&gt; s + parseFloat(x.replace(/\\\\s/g, \\&quot;\\&quot;)), 0);\\nconst STATS = [\\&quot;Force\\&quot;, \\&quot;Dextérité\\&quot;, \\&quot;Mental\\&quot;, \\&quot;Perception\\&quot;, \\&quot;Charisme\\&quot;];\\nconst norm = (s) =&gt; String(s).normalize(\\&quot;NFD\\&quot;).replace(/[\\\\u0300-\\\\u036f]/g, \\&quot;\\&quot;).toLowerCase().trim();\\nconst statIdx = (n) =&gt; { const x = norm(n); return STATS.findIndex((h) =&gt; norm(h) === x || (x.length &gt;= 3 &amp;&amp; norm(h).startsWith(x))); };\\n// Mini parseur YAML (clés, listes, listes d'objets, [inline], |, &gt;)\\nconst miniYaml = (src) =&gt; {\\n  const L = src.replace(/\\\\r/g, \\&quot;\\&quot;).replace(/\\\\t/g, \\&quot;  \\&quot;).split(\\&quot;\\\\n\\&quot;)\\n    .filter((l) =&gt; l.tri