n s.slice(1, -1);\\n    s = s.replace(/\\\\s+#.*$/, \\&quot;\\&quot;);\\n    if (/^\\\\[.*\\\\]$/.test(s)) return s.slice(1, -1).split(\\&quot;,\\&quot;).filter((x) =&gt; x.trim()).map(scal);\\n    if (s === \\&quot;\\&quot; || s === \\&quot;null\\&quot; || s === \\&quot;~\\&quot;) return null;\\n    if (/^-?\\\\d+(\\\\.\\\\d+)?$/.test(s)) return +s;\\n    if (s === \\&quot;true\\&quot; || s === \\&quot;false\\&quot;) return s === \\&quot;true\\&quot;;\\n    return s;\\n  };\\n  const block = (i, ind) =&gt; isItem(L[i].t) ? list(i, ind) : map(i, ind);\\n  const list = (i, ind) =&gt; {\\n    const arr = [];\\n    while (i &lt; L.length &amp;&amp; L[i].ind === ind &amp;&amp; isItem(L[i].t)) {\\n      const rest = L[i].t.slice(1).trim();\\n      if (!rest) { if (i + 1 &lt; L.length &amp;&amp; L[i + 1].ind &gt; ind) { const [v, j] = block(i + 1, L[i + 1].ind); arr.push(v); i = j; } else { arr.push(null); i++; } }\\n      else if (/^[^\\&quot;'\\\\[{][^:]*:(\\\\s|$)/.test(rest)) { L[i] = { ind: ind + L[i].t.indexOf(rest), t: rest }; const [v, j] = map(i, L[i].ind); arr.push(v); i = j; }\\n      else { arr.push(scal(rest)); i++; }\\n    }\\n    return [arr, i];\\n  };\\n  const map = (i, ind) =&gt; {\\n    const o = {};\\n    while (i &lt; L.length &amp;&amp; L[i].ind === ind &amp;&amp; !isItem(L[i].t)) {\\n      const m = L[i].t.match(/^(\\&quot;[^\\&quot;]*\\&quot;|'[^']*'|[^:]+?):(?:\\\\s+(.*))?$/);\\n      i++;\\n      if (!m) continue;\\n      const k = m[1].replace(/^[\\&quot;']|[\\&quot;']$/g, \\&quot;\\&quot;), v = (m[2] ?? \\&quot;\\&quot;).trim();\\n      if (/^[|&gt;][-+]?$/.test(v)) { const b = []; while (i &lt; L.length &amp;&amp; L[i].ind &gt; ind) b.push(L[i++].t); o[k] = b.join(v[0] === \\&quot;|\\&quot; ? \\&quot;\\\\n\\&quot; : \\&quot; \\&quot;); }\\n      else if (v === \\&quot;\\&quot; &amp;&amp; i &lt; L.length &amp;&amp; (L[i].ind &gt; ind || (L[i].ind === ind &amp;&amp; isItem(L[i].t)))) { const [val, j] = block(i, L[i].ind); o[k] = val; i = j; }\\n      else o[k] = scal(v);\\n    }\\n    return [o, i];\\n  };\\n  return L.length ? block(0, L[0].ind)[0] : null;\\n};\\nlet parseYaml = miniYaml;\\ntry { parseYaml = window.require(\\&quot;obsidian\\&quot;).parseYaml ?? miniYaml; } catch (e) {}\\n// Lecture synchrone d'une note (desktop) ; sur mobile, cache rempli au 1er rendu\\nconst cache = (window.__aerethiosCache ??= {});\\nconst read = (f) =&gt; {\\n  const fs = window.require?.(\\&quot;fs\\&quot;);\\n  if (fs &amp;&amp; app.vault.adapter.getFullPath) return fs.readFileSync(app.vault.adapter.getFullPath(f.path), \\&quot;utf8\\&quot;);\\n  app.vault.cachedRead(f).then((t) =&gt; (cache[f.path] = t));\\n  return cache[f.path] ?? \\&quot;\\&quot;;\\n};\\nconst FENCE = /^(```+|~~~+)(\\\\s*statblock[^\\\\n]*\\\\n)([\\\\s\\\\S]*?)^\\\\1/gm;\\nconst blocksOf = (f) =&gt; {\\n  if (!f) return [];\\n  const out = [];\\n  for (const m of read(f).matchAll(FENCE)) { try { const d = parseYaml(m[3]); if (d) out.push(d); } catch (e) {} }\\n  return out;\\n};\\n// \\&quot;body\\&quot;/\\&quot;shield\\&quot; : \\&quot;+5 AC\\&quot; / \\&quot;+Force AC\\&quot; / \\&quot;+Force(...) AC\\&quot; dans enchant -&gt; ac ; modificateur = (stat - 10) / 2 arrondi bas, x2 si (...) (minimum 0)\\nconst acOf = (d, st, warn) =&gt; {\\n  if (![\\&quot;body\\&quot;, \\&quot;shield\\&quot;].includes(String(d.category ?? \\&quot;\\&quot;).toLowerCase())) return d.ac;\\n  const descs = [d.enchant ?? []].flat(Infinity).map((e) =&gt; (e &amp;&amp; typeof e === \\&quot;object\\&quot; ? e.desc ?? \\&quot;\\&quot; : e)).join(\\&quot;\\\\n\\&quot;);\\n  let found = false, total = 0;\\n  // \\&quot;xx AC\\&quot; dans material.desc : ajouté tel quel\\n  const mat = [d.material ?? []].flat(Infinity).map((e) =&gt; (e &amp;&amp; typeof e === \\&quot;object\\&quot; ? e.desc ?? \\&quot;\\&quot; : e)).join(\\&quot;\\\\n\\&quot;);\\n  for (const m of String(mat).matchAll(/([+-]?)\\\\s*(\\\\d+(?:\\\\.\\\\d+)?)\\\\s*AC\\\\b/gi)) { found = true; total += (m[1] === \\&quot;-\\&quot; ? -1 : 1) * parseFloat(m[2]); }\\n  for (const m of String(descs).matchAll(/([+-])\\\\s*([\\\\p{L}\\\\d.]+?)\\\\s*(\\\\([^)]*\\\\))?\\\\s*AC\\\\b/giu)) {\\n    let v;\\n    if (/^\\\\d+(\\\\.\\\\d+)?$/.test(m[2])) v = parseFloat(m[2]);\\n    else {\\n      const k = statIdx(m[2]);\\n      if (k &lt; 0) { warn?.(`stat inconnue dans enchant (${m[2]})`); continue; }\\n      const mod = Math.floor((num(st[k]) - 10) / 2);\\n      v = m[3] ? Math.max(0, mod * 2) : mod; // (...) : x2, jamais négatif\\n    }\\n    found = true;\\n    total += m[1] === \\&quot;-\\&quot; ? -v : v;\\n  }\\n  // \\&quot;ac\\&quot; seulement si aucune valeur AC dans material / enchant\\n  return found ? total : d.ac;\\n};\\n\\n// Stats du joueur de la même note (bloc avec stats, sans category), lues seulement si besoin\\nlet st = null;\\nconst playerStats = () =&gt; (st ??= blocksOf(app.workspace.getActiveFile()).find((d) =&gt; Array.isArray(d.stats) &amp;&amp; d.category == null)?.stats ?? []);\\nconst statsProxy = new Proxy([], { get: (_, k) =&gt; playerStats()[k] });\\nconst dmgOf = (d, st = []) =&gt; {\\n  if (d.material == null &amp;&amp; d.gem == null &amp;&amp; d.enchant == null) return d.damage;\\n  const n = (v) =&gt; (String(v ?? \\&quot;\\&quot;).match(/[+-]?\\\\s*\\\\d+(\\\\.\\\\d+)?/g) ?? []).reduce((s, x) =&gt; s + parseFloat(x.replace(/\\\\s/g, \\&quot;\\&quot;)), 0);\\n  const txt = (x) =&gt; [x ?? []].flat(Infinity).map((e) =&gt; (e &amp;&amp; typeof e === \\&quot;object\\&quot; ? e.desc ?? \\&quot;\\&quot; : e)).join(\\&quot; \\&quot;);\\n  const body = [\\&quot;body\\&quot;, \\&quot;shield\\&quot;].includes(String(d.category ?? \\&quot;\\&quot;).toLowerCase()), unit = body ? \\&quot;DR\\&quot; : \\&quot;DMG\\&quot;;\\n  const dm = (s) =&gt; [...String(s).matchAll(body ? /([+-]?\\\\s*\\\\d+(?:\\\\.\\\\d+)?)\\\\s*(?:DMG|DR)\\\\b/gi : /([+-]?\\\\s*\\\\d+(?:\\\\.\\\\d+)?)\\\\s*DMG/gi)].reduce((a, m) =&gt; a + parseFloat(m[1].replace(/\\\\s/g, \\&quot;\\&quot;)), 0);\\n  const gems = d.gem == null ? [] : Array.isArray(d.gem) &amp;&amp; Array.isArray(d.gem[0]) ? d.gem : [d.gem];\\n  let total = dm(txt(d.material)) + gems.reduce((a, g) =&gt; a + (Array.isArray(g) ? n(g[1]) : 0), 0) + dm(txt(d.enchant));\\n  // body/shield : \\&quot;+Y * Stat(...) DR\\&quot; dans enchant -&gt; Y x modificateur (x2 et min 0 si (...))\\n  if (body) for (const m of txt(d.enchant).matchAll(/([+-])\\\\s*(\\\\d+(?:\\\\.\\\\d+)?)\\\\s*[*x×]\\\\s*([\\\\p{L}]+)\\\\s*(\\\\([^)]*\\\\))?\\\\s*DR\\\\b/giu)) {\\n    const k = statIdx(m[3]);\\n    if (k &lt; 0) continue;\\n    const mod = Math.floor((num(st[k]) - 10) / 2), v = m[4] ? Math.max(0, mod * 2) : mod;\\n    total += (m[1] === \\&quot;-\\&quot; ? -1 : 1) * parseFloat(m[2]) * v;\\n  }\\n  return total ? `${total} ${unit}` : null; // 0 -&gt; rien\\n};\\n// Dégâts / DR calculés ici (stats du joueur dispo), affichés par le bloc \\&quot;+ dégâts\\&quot;\\nmonster.__dmg = dmgOf(monster, statsProxy);\\n\\n// Valeur affichée par le heading \\&quot;ac_calc\\&quot; ; \\&quot;ac\\&quot; n'est jamais modifié (sinon il s'additionne à chaque rendu)\\nconst ac = acOf(monster, statsProxy);\\nif (ac != null &amp;&amp; String(ac).trim() !== \\&quot;\\&quot;) monster.ac_calc = `${ac} AC`;&quot;},{&quot;type&quot;:&quot;inline&quot;,&quot;id&quot;:&quot;98f89b1b1999&quot;,&quot;properties&quot;:[],&quot;nested&quot;:[{&quot;type&quot;:&quot;group&quot;,&quot;id&quot;:&quot;7bb90b7998bb&quot;,&quot;properties&quot;:[],&quot;nested&quot;:[{&quot;type&quot;:&quot;heading&quot;,&quot;id&quot;:&quot;4a49290b780a&quot;,&quot;properties&quot;:[&quot;name&quot;],&quot;size&quot;:1,&quot;fallback&quot;:&quot;-&quot;,&quot;conditioned&quot;:true},{&quot;type&quot;:&quot;text&quot;,&quot;id&quot;:&quot;991908cbcb79&quot;,&quot;properties&quot;:[&quot;type&quot;],&quot;text&quot;:null,&quot;fallback&quot;:&quot;&quot;,&quot;headingProp&quot;:false,&quot;heading&quot;:&quot;&quot;,&quot;conditioned&quot;:true}]},{&quot;type&quot;:&